#pragma once
#include "LalalCredentials.h"
class LalalSettings final:public juce::Component{
 juce::Label title,info,status;juce::TextEditor key;juce::TextButton save{"SAVE KEY"},remove{"REMOVE KEY"};
public:
 LalalSettings(){setSize(440,290);for(auto* c:std::vector<juce::Component*>{&title,&info,&status,&key,&save,&remove})addAndMakeVisible(c);title.setText("LALAL.AI - HQ EXPORT ONLY",juce::dontSendNotification);title.setBounds(12,8,416,28);info.setText("Enter your API key from your LALAL.AI account. It is stored in macOS Keychain, never in presets or Ableton Sets.\n\nCloud HQ uploads only the export region (plus timing context) and uses billed minutes. Drums/Bass/Vocals need one separation type; Harmonics may need all three. Results are cached locally. Playback stays local.\n\nSave enables LALAL.AI in the HQ export selector. GPU and Safe CPU remain available for local HQ.",juce::dontSendNotification);info.setFont(juce::FontOptions(12));info.setBounds(12,38,416,148);key.setBounds(12,190,416,27);key.setPasswordCharacter(juce::CharPointer_UTF8("\xe2\x80\xa2").getAndAdvance());key.setTextToShowWhenEmpty((bool)LibraryStore::read("settings.json").getProperty("lalalKeySaved",false)?"Key saved - enter a replacement":"Paste LALAL.AI API key",juce::Colours::grey);save.setBounds(12,225,202,28);remove.setBounds(226,225,202,28);status.setBounds(12,258,416,24);status.setFont(juce::FontOptions(11));save.onClick=[this]{juce::String error;if(!LalalCredentials::save(key.getText(),error)){status.setText(error,juce::dontSendNotification);return;}key.clear();LibraryStore::update("settings.json",[](juce::DynamicObject& o){o.setProperty("lalalKeySaved",true);o.setProperty("lalalCloudHQ",true);});key.setTextToShowWhenEmpty("Key saved - enter a replacement",juce::Colours::grey);status.setText("Key saved. LALAL.AI selected for HQ exports.",juce::dontSendNotification);};remove.onClick=[this]{juce::String error;if(!LalalCredentials::remove(error)){status.setText(error,juce::dontSendNotification);return;}key.clear();LibraryStore::update("settings.json",[](juce::DynamicObject& o){o.setProperty("lalalKeySaved",false);o.setProperty("lalalCloudHQ",false);});key.setTextToShowWhenEmpty("Paste LALAL.AI API key",juce::Colours::grey);status.setText("Key removed. Local HQ selected.",juce::dontSendNotification);};}
};
